SELECT run_id FROM int_sync_project_scope_publication
WHERE tenant_id=#{query.tenantId} AND source_connection_id=#{query.connectionId}
ORDER BY published_at DESC, run_id DESC LIMIT 1

SELECT  FROM int_sync_project_scope_member
WHERE tenant_id=#{query.tenantId} AND source_connection_id=#{query.connectionId} AND run_id=#{query.runId}


    AND source_project_key IN #{key}

  AND 1=0

ORDER BY source_project_key

SELECT  FROM int_sync_project_scope_member
WHERE tenant_id=#{query.tenantId} AND source_connection_id=#{query.connectionId} AND run_id=#{query.runId}
  AND source_project_key > #{query.afterKey}
ORDER BY source_project_key LIMIT 500
